#!/usr/bin/env bash
# Instala /entrevista en CRconecta/tu-match-profesional. Ejecutar desde la raíz del repo.
set -e
[ -f package.json ] && [ -d app ] || { echo "Ejecutá este script en la raíz del repo tu-match-profesional"; exit 1; }
echo "" | base64 -d | tar xz
python3 - <<'PY'
p='app/page.tsx'; s=open(p).read()
old='<a href="#tipos-de-cv" onClick={() => setIsMenuOpen(false)}>Tipos de CV</a>'
if '/entrevista' not in s:
    assert old in s, 'No encontré el menú en app/page.tsx'
    open(p,'w').write(s.replace(old, old+'<a href="/entrevista">Entrevistas</a>'))
PY
npm install --no-audit --no-fund
npm run build
git add app lib
git commit -m "Agrega /entrevista: generador de entrevistas por competencias"
git push
echo "Listo. Cuando Netlify termine el deploy, probá: https://tumatchprofesional.netlify.app/entrevista"
